-- ============================================================
-- SEED EXT 6: Módulo 22 — Subjunctive (ex 199-300)
-- Blocos 71-83 | 102 exercícios
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'subjunctive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo subjunctive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Present subjunctive — recommend/require that (8 ex)
  (cid,71,199,'gap_fill','The committee recommends that the government _____ (commission) an independent review of the current framework and that the review _____ (complete/passive) within six months.','commission / be completed',NULL,'''Recommend that + subject + base verb'' (present subjunctive, no -s in third person); ''be completed'' = passive subjunctive.','medium'),
  (cid,71,200,'gap_fill','The report requires that all institutions _____ (submit) detailed accounts of their expenditure and that these accounts _____ (audit/passive) annually by an independent body.','submit / be audited',NULL,'''Require that + subject + base verb'' (no -s); ''be audited'' = passive subjunctive.','medium'),
  (cid,71,201,'gap_fill','The panel insists that the minister _____ (appear) before the committee and that full _____ (document → noun) _____ (provide/passive) within fourteen days.','appear / documentation / be provided',NULL,'''Insist that + subject + base verb''; ''documentation be provided'' = noun + passive subjunctive.','medium'),
  (cid,71,202,'gap_fill','The board demands that the director _____ (resign) immediately and that a _____ (comprehensive) _____ (review → noun) of _____ (her) _____ (decision) _____ (undertake/passive) by _____ (an) _____ (independent) _____ (body).','resign / comprehensive / review / her / decisions / be undertaken / an / independent / body',NULL,'''Demand that + subject + base verb'' (resign); ''review be undertaken'' = passive subjunctive.','hard'),
  (cid,71,203,'gap_fill','The legislation stipulates that every public institution _____ (publish) an annual performance report and that the report _____ (make/passive) freely available to the public.','publish / be made',NULL,'''Stipulate that + subject + base verb'' (present subjunctive); ''be made available'' = passive subjunctive.','medium'),
  (cid,71,204,'gap_fill','The framework mandates that each regulatory authority _____ (establish) an independent complaints procedure and that all complaints _____ (resolve/passive) within thirty working days.','establish / be resolved',NULL,'''Mandate that + subject + base verb'' (no -s); ''be resolved'' = passive subjunctive.','medium'),
  (cid,71,205,'gap_fill','The convention proposes that member states _____ (adopt) a uniform reporting standard and that compliance _____ (verify/passive) through a _____ (mutual) _____ (peer/noun) _____ (review → noun) _____ (process).','adopt / be verified / mutual / peer / review / process',NULL,'''Propose that + subject + base verb'' + ''compliance be verified through peer review.''','medium'),
  (cid,71,206,'multiple_choice','Which sentence CORRECTLY uses the present subjunctive?','The protocol requires that each member state submit a detailed progress report by the end of the fiscal year.','[''The protocol requires that each member state submits a detailed progress report by the end of the fiscal year.'',''The protocol requires that each member state to submit a detailed progress report by the end of the fiscal year.'',''The protocol requires that each member state submit a detailed progress report by the end of the fiscal year.'',''The protocol requires that each member state would submit a detailed progress report by the end of the fiscal year.'']','Option C: subjunctive = base form (no -s, no to, no would) after ''requires that.''','easy'),

  -- BLOCK 72: Demand/insist/mandate — advanced formal contexts (8 ex)
  (cid,72,207,'gap_fill','The constitutional court ordered that the legislature _____ (reconvene) within seven days and that _____ (all) _____ (pass/passive) _____ (legislation) _____ (from/the/previous/session) _____ (subject/passive) _____ (to) _____ (comprehensive) _____ (constitutional) _____ (review).','reconvene / all / passed / legislation / from the previous session / be subjected / to / comprehensive / constitutional / review',NULL,'''Order that + subject + base verb'' (reconvene); complex passive: ''legislation be subjected to review.''','hard'),
  (cid,72,208,'gap_fill','The charter requires that any _____ (propose/adjective) _____ (amendment) _____ (circulate/passive) to all member states at least sixty days in advance and that no amendment _____ (adopt/passive) without a two-thirds _____ (majority).','proposed / amendment / be circulated / be adopted / majority',NULL,'''Require that + noun + be + past participle'' = passive subjunctive; ''no amendment be adopted'' = negative subjunctive.','hard'),
  (cid,72,209,'gap_fill','The audit committee urges that _____ (immediate) _____ (step) _____ (take/passive) to address the _____ (deficiency) _____ (identify/passive) and that a _____ (comprehensive) _____ (action) _____ (plan) _____ (develop/passive) _____ (within) _____ (ninety) _____ (day).','immediate / steps / be taken / deficiencies / identified / comprehensive / action / plan / be developed / within / ninety / days',NULL,'''Urge that + noun + be + past participle'' (steps be taken, plan be developed); deficiencies identified = reduced relative.','hard'),
  (cid,72,210,'gap_fill','International law demands that states _____ (ensure) that any deprivation of liberty _____ (subject/passive) to independent judicial review and that no person _____ (detain/passive) without _____ (access) to _____ (legal) _____ (counsel).','ensure / be subjected / be detained / access / legal / counsel',NULL,'''Demand that states ensure that...be subjected'' = nested subjunctive; ''no person be detained'' = negative subjunctive.','hard'),
  (cid,72,211,'gap_fill','The _____ (oversight) _____ (body) _____ (move → noun/proposal) that the _____ _____ (minister/resign) and that a _____ (comprehensive) _____ (investigation/undertake/passive) before any _____ (appointment) _____ _____ (of a/successor) _____ (proceed).','oversight / body / moved / minister / resign / comprehensive / investigation be undertaken / appointment / of a successor / proceed',NULL,'''Move (= formally propose) that minister resign'' (present subjunctive); ''investigation be undertaken before appointment proceed'' (two more subjunctives).','hard'),
  (cid,72,212,'gap_fill','The _____ (resolution) _____ (calls) _____ (for) the _____ (secretary-general) to _____ (recommend) that the _____ (security) _____ (council) _____ (consider) _____ (additional) _____ (measure) and _____ (that) the _____ (member) _____ (state) _____ _____ (most/affect/passive) _____ (receive) _____ (immediate) _____ (humanitarian) _____ (assistance).','resolution / calls / for / secretary-general / recommend / security / council / consider / additional / measures / that / member / states / most affected / receive / immediate / humanitarian / assistance',NULL,'''Recommend that the council consider...and that states...receive'' = subjunctive after ''recommend that.''','hard'),
  (cid,72,213,'gap_fill','The _____ (conference) _____ (declare → noun/noun) _____ (urge) that _____ (international) _____ (financial) _____ (institution) _____ (restructure/passive) to _____ (better) _____ (reflect) the _____ (contemporary) _____ (balance) of _____ (economic) _____ (power) and that _____ (voting) _____ (right) _____ (reallocate/passive) _____ (accordingly).','conference / declaration / urged / international / financial / institutions / be restructured / better / reflect / contemporary / balance / economic / power / voting / rights / be reallocated / accordingly',NULL,'''Urge that institutions be restructured...and that rights be reallocated'' = parallel passive subjunctives.','hard'),
  (cid,72,214,'multiple_choice','Which sentence correctly uses the subjunctive after ''insist''?','The director insists that all staff members be present at the emergency meeting.','[''The director insists that all staff members are present at the emergency meeting.'',''The director insists that all staff members were present at the emergency meeting.'',''The director insists that all staff members be present at the emergency meeting.'',''The director insists that all staff members to be present at the emergency meeting.'']','Option C: ''insist that + subject + base form'' (be, not are/were/to be).','easy'),

  -- BLOCK 73: It is + adjective + that (vital/essential/crucial/necessary/imperative) (8 ex)
  (cid,73,215,'gap_fill','It is essential that the _____ (review) _____ (conduct/passive) independently and that its _____ (find → noun) _____ (make/passive) _____ (public) without _____ (political) _____ (interference).','review / be conducted / findings / be made / public / political / interference',NULL,'''It is essential that + subject + be + past participle'' = formal subjunctive with adjective trigger.','medium'),
  (cid,73,216,'gap_fill','It is vital that all _____ (stakeholder) _____ (have) the opportunity to _____ (contribute) to the _____ (consultation) process and that their _____ (contribution) _____ (take/passive) _____ (seriously) in the _____ (final) _____ (decision) _____ (make → noun).','stakeholders / have / contribute / consultation / contributions / be taken / seriously / final / decision / making',NULL,'''It is vital that stakeholders have...and that contributions be taken seriously.''','medium'),
  (cid,73,217,'gap_fill','It is crucial that the _____ (evidence) _____ (assess/passive) _____ (rigorously) before any _____ (conclusion) _____ (draw/passive) and that the _____ (limitation) of the _____ (analysis) _____ (acknowledge/passive) _____ (explicit/adverb).','evidence / be assessed / rigorously / conclusions / be drawn / limitations / analysis / be acknowledged / explicitly',NULL,'''It is crucial that evidence be assessed...conclusions be drawn...limitations be acknowledged'' = three parallel passive subjunctives.','hard'),
  (cid,73,218,'gap_fill','It is _____ (imperative) that the _____ (government) _____ (address) the _____ (underlying) _____ (cause) of the _____ (crisis) rather than _____ (merely) _____ (treat/gerund) its _____ (symptom) and that any _____ _____ (measure/adopt/passive) _____ (be) _____ _____ (durable) _____ (and/sustainable).','imperative / government / address / underlying / causes / crisis / merely / treating / symptoms / measures adopted / be / durable / sustainable',NULL,'''It is imperative that government address causes...and that measures adopted be durable'' = present + passive subjunctive.','hard'),
  (cid,73,219,'gap_fill','It is _____ (necessary) that the _____ (agency) _____ (develop) clear _____ (criterion) for _____ (prioritize/gerund) _____ (intervention) and that these _____ (criterion) _____ (apply/passive) _____ (consistently) across all _____ (case) _____ (come/gerund) before it.','necessary / agency / develop / criteria / prioritizing / interventions / criteria / be applied / consistently / cases / coming',NULL,'''It is necessary that agency develop criteria...and that criteria be applied consistently.''','hard'),
  (cid,73,220,'gap_fill','It is _____ (advisable) that the _____ (panel) _____ (seek) _____ (independent) _____ (technical) _____ (advice) before _____ (reach/gerund) a _____ _____ (conclusion) and that any _____ (recommendation) _____ (base/passive) _____ (on) _____ (the) _____ (best) _____ _____ (available) _____ (evidence).','advisable / panel / seek / independent / technical / advice / reaching / conclusion / recommendation / be based / on / the / best / available / evidence',NULL,'''It is advisable that panel seek advice...and that recommendation be based on evidence.''','hard'),
  (cid,73,221,'gap_fill','It is _____ (important) that the _____ (process) _____ (be) _____ (transparent), that _____ (all) _____ (interested) _____ (party) _____ (have) _____ (access) _____ (to) _____ (the) _____ (relevant) _____ _____ (information), and that _____ (any) _____ (decision) _____ (reach/passive) _____ (be) _____ (adequately) _____ (justify/passive).','important / process / be / transparent / all / interested / parties / have / access / to / the / relevant / information / any / decision / reached / be / adequately / justified',NULL,'''It is important that process be transparent, parties have access, decision be adequately justified'' = three subjunctives.','hard'),
  (cid,73,222,'multiple_choice','Which sentence CORRECTLY uses the subjunctive after ''It is essential''?','It is essential that the data be verified independently before any conclusions are published.','[''It is essential that the data is verified independently before any conclusions are published.'',''It is essential that the data being verified independently before any conclusions are published.'',''It is essential that the data be verified independently before any conclusions are published.'',''It is essential that the data to be verified independently before any conclusions are published.'']','Option C: ''It is essential that + subject + be + past participle'' = passive subjunctive. Not ''is,'' not ''being,'' not ''to be.''','easy'),

  -- BLOCK 74: Past subjunctive — wish/if only (8 ex)
  (cid,74,223,'gap_fill','The reformers _____ (wish) they _____ (have/past) appreciated the complexity of implementation before designing the program — if only they _____ (know/past) what they know now, many costly errors _____ (might/avoid/passive).','wished / had / had known / might have been avoided',NULL,'''Wished they had'' = past perfect after wish (reference to past); ''if only they had known'' = same; ''might have been avoided.''','medium'),
  (cid,74,224,'gap_fill','_____ (If/only) the evidence _____ (be) stronger, it _____ (would/be) _____ (considerably) _____ (easier) to _____ (make) _____ (a) _____ _____ _____ (compelling/case) for _____ (immediate) _____ (action) — as it _____ (is/stand/passive), the _____ (uncertainty) _____ _____ _____ (surrounding) _____ (the) _____ (find → noun) _____ (make) _____ (caution) _____ (advisable).','If only / were / would be / considerably / easier / make / a / compelling case / immediate / action / stands / uncertainty / surrounding / findings / makes / caution / advisable',NULL,'''If only the evidence were stronger, it would be'' = present subjunctive with ''if only'' (unreal present).','hard'),
  (cid,74,225,'gap_fill','The _____ (researcher) _____ (wishes) that _____ (she) _____ (have/past) _____ (access) to a _____ (larger) _____ (sample) — if _____ _____ (she) _____ (do/past), the _____ (generalize → noun) of the _____ _____ (finding → noun) _____ (would/be) _____ (considerably) _____ (more) _____ (robust).','researcher / wishes / she / had / access / larger / sample / she / did / generalizability / findings / would be / considerably / more / robust',NULL,'''Wishes she had had access'' (past perfect after wish for past regret); ''if she did'' (past simple for unreal present).','hard'),
  (cid,74,226,'gap_fill','The _____ (minister) _____ (wish) the _____ (evidence) _____ (be) clearer — _____ (if/only) it _____ (were), the _____ (decision) _____ (would) be _____ (considerably) _____ (more) _____ _____ (straightforward). As it _____ (be), she _____ (face) the _____ (prospect) of _____ (act/gerund) on _____ (incomplete) _____ (information).','minister / wishes / evidence / were / if only / were / decision / would / considerably / more / straightforward / is / faces / prospect / acting / incomplete / information',NULL,'''Wishes the evidence were clearer'' (unreal present); ''if only it were, decision would be more straightforward.''','hard'),
  (cid,74,227,'gap_fill','If _____ (only) _____ (the) _____ (field) _____ (have/past) _____ (develop/past) more _____ (robust) _____ (methodological) _____ (tool) _____ (earlier), it _____ (would/be) in a _____ _____ (strong) _____ (position) _____ (today) to _____ _____ (provide) _____ (evidence-based) _____ (guidance) to _____ (practitioner).','only / the / field / had / developed / robust / methodological / tools / earlier / would be / stronger / position / today / provide / evidence-based / guidance / practitioners',NULL,'''If only the field had developed tools earlier, it would be in a stronger position today'' = past regret with present result.','hard'),
  (cid,74,228,'gap_fill','The _____ (organization) _____ (wish) it _____ (have/past) _____ (anticipate) the _____ (degree) of _____ (resistance) it _____ (would) _____ (encounter) — had it _____ (do/past) _____ (so), it _____ (would/deploy) _____ _____ (additional) _____ (resource) to _____ _____ _____ (manage) the _____ (transition) more _____ (effectively).','organization / wishes / had / anticipated / degree / resistance / would / encounter / done / so / would have deployed / additional / resources / manage / transition / effectively',NULL,'''Wishes it had anticipated'' (past perfect after wish); ''had it done so, would have deployed'' = inverted third conditional.','hard'),
  (cid,74,229,'gap_fill','The _____ (researcher) _____ (wished) that _____ (the) _____ (peer/noun) _____ (review) _____ (process) _____ (have) _____ (flag/past) _____ (the) _____ (problem) before _____ (publication) — _____ (if) only _____ (it) _____ (have/past), the _____ _____ (embarrass → noun/passive) _____ (of) _____ (a) _____ (subsequent) _____ (retract → noun) _____ (could/avoid/passive).','researcher / wished / the / peer / review / process / had / flagged / the / problem / publication / if / only / it / had / embarrassment / of / a / subsequent / retraction / could have been avoided',NULL,'''Wished the process had flagged'' + ''if only it had, embarrassment of retraction could have been avoided.''','hard'),
  (cid,74,230,'multiple_choice','Which sentence CORRECTLY uses the past subjunctive with ''wish''?','The committee wishes the evidence were more conclusive.','[''The committee wishes the evidence was more conclusive.'',''The committee wishes the evidence would be more conclusive.'',''The committee wishes the evidence is more conclusive.'',''The committee wishes the evidence were more conclusive.'']','Option D: ''wish + past subjunctive (were)'' for unreal present. ''Was'' is also accepted informally, but ''were'' is the formal subjunctive form.','medium'),

  -- BLOCK 75: As if / as though + past subjunctive (8 ex)
  (cid,75,231,'gap_fill','The minister spoke as if she _____ (have) complete certainty about the outcome — as though the _____ (evidence) already _____ (establish/passive) beyond doubt what _____ (could) only be _____ (establish/passive) through _____ (further) _____ (research).','had / evidence / had been established / could / be established / further / research',NULL,'''As if she had'' (past subjunctive for unreal present); ''as though the evidence had been established'' (past perfect subjunctive).','hard'),
  (cid,75,232,'gap_fill','The institution _____ (behave) as if it _____ (be) _____ (immune) to external _____ (scrutiny) — as though the _____ (normal) _____ (rule) of _____ (accountable → noun) simply _____ (not/apply) to _____ _____ _____ (its/own/operation).','behaved / were / immune / scrutiny / normal / rules / accountability / did not apply / its own operations',NULL,'''As if it were immune'' (present subjunctive for unreal); ''as though rules did not apply'' (past simple for unreal present).','hard'),
  (cid,75,233,'gap_fill','The _____ (rhetoric) of _____ (the) _____ (reform) _____ (sound) as though _____ (fundamental) _____ (change) _____ (already/achieve/passive) — as if the _____ (mere) _____ _____ (announce → noun) _____ (of) _____ _____ _____ _____ (new/initiative) _____ (were) _____ _____ _____ (sufficient) _____ _____ _____ _____ (to/bring/it/about).','rhetoric / the / reform / sounded / fundamental / change / had already been achieved / mere / announcement / of / new initiatives / were / sufficient / to bring it about',NULL,'''As though fundamental change had already been achieved'' (past perfect subjunctive); ''as if the announcement were sufficient.''','hard'),
  (cid,75,234,'gap_fill','Practitioners often _____ (speak) as if _____ (governance) _____ (reform) _____ _____ (were) _____ (simple) _____ _____ _____ (once/the/right/design/choose/passive) — as though the _____ (difficult) _____ (question) were _____ (the) _____ _____ (technical) _____ (one/rather) than the _____ (political) _____ (one).','speak / governance / reform / were / simple / once the right design were chosen / difficult / question / were / the / technical / one rather / political / one',NULL,'''As if reform were simple once design were chosen'' (two past subjunctives); ''as though the question were technical not political.''','hard'),
  (cid,75,235,'gap_fill','The _____ (institution) _____ (act) as _____ (though) _____ (it) _____ (have) _____ (nothing) _____ (to) _____ (learn) from _____ (comparable) _____ (organization) elsewhere — as if _____ (its) _____ (own) _____ (experience) _____ (alone) _____ (were) _____ (sufficient) to _____ (guide) _____ _____ (sound) _____ (decision-make → noun).','institution / acts / though / it / has / nothing / to / learn / comparable / organizations / its / own / experience / alone / were / sufficient / guide / sound / decision-making',NULL,'''Acts as though it has nothing to learn'' (as though + indicative for weak contrast); ''as if experience alone were sufficient'' (subjunctive for unreal).','hard'),
  (cid,75,236,'gap_fill','The author _____ (write) as if _____ (the) _____ (answer) _____ _____ _____ _____ (already/know/passive) — as though _____ (the) _____ (only) _____ (task) _____ _____ _____ _____ _____ _____ (that/remain) _____ _____ _____ _____ _____ (were/to/communicate/the/finding) clearly to a _____ _____ _____ (non-specialist) _____ (audience).','writes / the / answers / were / already / known / the / only / task / that / remains / were to communicate the findings / non-specialist / audience',NULL,'''As if the answers were already known'' (past subjunctive) + ''as though the only task that remains were to communicate.''','hard'),
  (cid,75,237,'gap_fill','The _____ (funding) _____ (body) _____ (speak) as if _____ (rigorous) _____ _____ _____ (peer/noun) _____ (review) _____ _____ _____ _____ _____ _____ _____ _____ _____ (were/guarantee/of/quality) rather than _____ _____ _____ _____ (merely/a/necessary/condition) _____ _____ _____ _____ (for/it) — _____ (as) _____ (though) _____ _____ _____ (there) _____ (were) _____ (no) _____ (known) _____ _____ _____ _____ _____ (case/of/peer-review/fail).','funding / body / speaks / rigorous / peer / review / were a guarantee of quality / merely a necessary condition / for it / as / though / there / were / no / known / cases of peer review failing',NULL,'''As if peer review were a guarantee'' (past subjunctive); ''as though there were no known cases of failure.''','hard'),
  (cid,75,238,'multiple_choice','Which sentence CORRECTLY uses ''as if'' with the past subjunctive?','The organization behaves as if it were immune to the kinds of accountability pressures that other public bodies face.','[''The organization behaves as if it is immune to accountability pressures.'',''The organization behaves as if it was immune to accountability pressures.'',''The organization behaves as if it were immune to the kinds of accountability pressures that other public bodies face.'',''The organization behaves as if it has been immune to accountability pressures.'']','Option C: ''as if + were'' = formal past subjunctive for unreal present. ''Was'' (B) is informally accepted; ''is'' (A) implies it''s actually true; ''has been'' (D) is past perfect, wrong tense here.','medium'),

  -- BLOCK 76: Would rather + past subjunctive (8 ex)
  (cid,76,239,'gap_fill','The committee _____ (would) _____ (rather) the _____ (evidence) _____ (be/not) released until the _____ (investigation) is _____ (complete) — it would prefer that all _____ (relevant) _____ _____ (party) _____ (have) the _____ (opportunity) to _____ (respond) before _____ (public) _____ (disclosure).','would / rather / evidence / were not released / investigation / complete / relevant / parties / have / opportunity / respond / public / disclosure',NULL,'''Would rather + subject + past subjunctive (were not released)'' = unreal present preference; ''would prefer that parties have.''','hard'),
  (cid,76,240,'gap_fill','The _____ (researcher) _____ (would) _____ (rather) the _____ (result) _____ _____ _____ _____ _____ _____ _____ (had/been/more/straightforward) — _____ _____ _____ _____ _____ _____ _____ _____ _____ (it/would/be/considerably/easier/to/communicate/them) to a general _____ (audience) and to _____ _____ _____ _____ _____ _____ (draw/clear/policy/implication).','researcher / would / rather / results / had been more straightforward / it would be considerably easier to communicate them / audience / draw clear policy implications',NULL,'''Would rather + subject + past perfect'' (had been) = unreal past regret; ''it would be easier'' = present result.','hard'),
  (cid,76,241,'gap_fill','_____ (Many) _____ (observer) _____ _____ _____ (would/rather) the _____ _____ _____ _____ _____ _____ _____ (government/had/proceed/more/cautiously) before _____ _____ _____ _____ _____ _____ _____ (committing/itself/to/the/reform) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (had/it/do/so/much/of/the/subsequent/criticism/might/avoid/passive).','Many / observers / would rather / government / had proceeded more cautiously / committing itself to the reform / had it done so much of the subsequent criticism might have been avoided',NULL,'''Would rather government had proceeded'' (past perfect subjunctive for past regret) + ''had it done so...might have been avoided'' (inverted conditional).','hard'),
  (cid,76,242,'gap_fill','The _____ (government) _____ _____ _____ (would/rather) the _____ (review) _____ (reach) its _____ (conclusion) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (before/the/end/of/the/parliamentary/term) — it _____ _____ _____ _____ _____ _____ _____ (would/prefer/that/a/decision/take/passive) _____ _____ _____ _____ (while/it/still/has/the/authority) to _____ (implement) it.','government / would rather / review / reached / conclusions / before the end of the parliamentary term / would prefer that a decision be taken / while it still has the authority / implement',NULL,'''Would rather the review reached'' (past simple = unreal present) + ''prefer that a decision be taken'' (present subjunctive).','hard'),
  (cid,76,243,'gap_fill','The _____ _____ _____ (board/would/rather) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (director/not/resign/before/the/inquiry/complete/passive) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (it/would/prefer/that/he/remain/in/post) until his _____ (successor) _____ _____ (formally/appoint/passive).','board would rather / director / not resign before the inquiry were completed / it would prefer that he remain in post / successor / formally appointed',NULL,'''Would rather director not resign before inquiry were completed'' (past subjunctive); ''prefer that he remain'' (present subjunctive).','hard'),
  (cid,76,244,'gap_fill','_____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (It/goes/without/saying/that/the/committee/would/rather/the/findings/have/been/different) — the _____ _____ _____ (evidence/as/it) _____ (stand/passive) _____ (leave) no _____ _____ _____ _____ _____ _____ (comfortable/interpretation/available).','It goes without saying that the committee would rather the findings had been different / evidence as it stands / leaves / comfortable interpretation available',NULL,'''Would rather the findings had been different'' (past perfect subjunctive for past regret); ''evidence as it stands.''','hard'),
  (cid,76,245,'gap_fill','The _____ (panel) _____ _____ _____ (would/prefer) that the _____ (decision) _____ _____ (be/unanimous) — it _____ _____ _____ _____ _____ _____ (would/rather/a/divided/vote/not/reflect) _____ _____ _____ _____ (the/depth/of/disagreement) that _____ _____ _____ _____ (in/fact/existed) _____ _____ _____ _____ _____ (among/its/member) _____ _____ _____ _____ _____ (on/this/critical/question).','panel / would prefer / decision / were unanimous / would rather a divided vote not reflect / the depth of disagreement / in fact existed / among its members / on this critical question',NULL,'''Would prefer the decision were unanimous'' (past subjunctive); ''would rather a divided vote not reflect...disagreement.''','hard'),
  (cid,76,246,'multiple_choice','Which sentence CORRECTLY uses ''would rather'' with the past subjunctive?','The director would rather the committee delayed its decision until the investigation was complete.','[''The director would rather the committee delays its decision until the investigation is complete.'',''The director would rather the committee delay its decision until the investigation is complete.'',''The director would rather the committee delayed its decision until the investigation was complete.'',''The director would rather the committee will delay its decision.'']','Option C: ''would rather + subject + past simple'' = standard pattern for present wish about someone else''s action. Option B also works (base form treated as subjunctive).','medium'),

  -- BLOCK 77: Lest + present subjunctive (8 ex)
  (cid,77,247,'gap_fill','The _____ (report) _____ (should) _____ (include) explicit _____ (caveat) about the _____ (limitation) of its _____ (finding) lest _____ (reader) _____ (interpret) them as more _____ (conclusive) than the _____ (evidence) _____ (warrant).','report / should / include / caveats / limitations / findings / readers / interpret / conclusive / evidence / warrants',NULL,'''Lest readers interpret'' = subjunctive or present simple after ''lest'' (formal: no -s in subjunctive; ''lest'' = for fear that).','hard'),
  (cid,77,248,'gap_fill','The _____ (government) _____ (must) _____ (act) _____ (quickly) lest _____ (the) _____ (window) _____ _____ (of/opportunity) _____ (close) — _____ (delay) _____ (risk) _____ (allow/gerund) _____ _____ (opposition) to _____ _____ _____ (organize/and/mobilize/passive).','government / must / act / quickly / lest / the / window / of opportunity / close / delay / risks / allowing / opposition / organize and mobilize',NULL,'''Lest the window close'' (present subjunctive = base form); ''risks allowing opposition to organize.''','hard'),
  (cid,77,249,'gap_fill','Care _____ (should) _____ (take/passive) in _____ _____ _____ (interpreting/these/result) lest _____ (an) _____ (overly) _____ _____ (optimistic) _____ (reading) _____ (create) _____ (unrealistic) _____ (expectation) that _____ (ultimately) _____ _____ (undermine) _____ (support) _____ _____ _____ _____ (for/the/reform/agenda).','should / be taken / interpreting these results / an / overly / optimistic / reading / create / unrealistic / expectations / ultimately / undermine / support / for the reform agenda',NULL,'''Lest an overly optimistic reading create unrealistic expectations'' (present subjunctive); care = passive.','hard'),
  (cid,77,250,'gap_fill','The _____ (oversight) _____ (framework) _____ (must) _____ (maintain) _____ (clear) _____ _____ (boundary) between _____ (regulation) and _____ _____ (operation) lest _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/regulator/come/to/serve/the/interest/of/those/it/regulate) rather than _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (those/in/the/public/interest/whom/it/is/design/passive/to/protect).','oversight / framework / must / maintain / clear / boundaries / regulation / operations / the regulator come to serve the interests of those it regulates / those in the public interest whom it is designed to protect',NULL,'''Lest the regulator come to serve interests'' (present subjunctive) = regulatory capture concern.','hard'),
  (cid,77,251,'gap_fill','The _____ (researcher) _____ (must) _____ (acknowledge) _____ _____ _____ _____ _____ _____ _____ _____ (the/limitation/of/the/methodology) lest _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/reader/be/mislead/passive/into/overclaiming/on/the/basis/of/the/analysis).','researcher / must / acknowledge / the limitations of the methodology / the reader be misled into overclaiming on the basis of the analysis',NULL,'''Lest the reader be misled'' = present passive subjunctive (be misled = base form passive); academic epistemic responsibility.','hard'),
  (cid,77,252,'gap_fill','Practitioners _____ (should) _____ _____ _____ _____ _____ _____ _____ _____ _____ (resist/the/temptation/to/adopt/simple/solution) lest _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/complexity/of/the/challenge/be/underestimate/passive/and/the/intervention/consequently/be/design/passive/inadequately).','should / resist the temptation to adopt simple solutions / the complexity of the challenge be underestimated and the intervention consequently be designed inadequately',NULL,'''Lest the complexity be underestimated and the intervention be designed inadequately'' = two parallel passive subjunctives.','hard'),
  (cid,77,253,'gap_fill','The _____ (board) _____ _____ _____ _____ _____ _____ _____ _____ (must/not/rush/its/deliberation) lest _____ _____ _____ _____ _____ _____ _____ _____ (a/decision/of/such/consequence/reach/passive) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (without/the/full/deliberation/that/its/importance/warrant).','board / must not rush its deliberations / a decision of such consequence be reached / without the full deliberation that its importance warrants',NULL,'''Lest a decision of such consequence be reached without the full deliberation'' = passive subjunctive with elaborate noun phrase.','hard'),
  (cid,77,254,'multiple_choice','Which sentence CORRECTLY uses ''lest'' with the subjunctive?','The findings must be carefully qualified lest the reader draw conclusions that the evidence does not support.','[''The findings must be carefully qualified lest the reader draws conclusions that evidence doesn''t support.'',''The findings must be carefully qualified lest the reader to draw conclusions that evidence doesn''t support.'',''The findings must be carefully qualified lest the reader drew conclusions that the evidence does not support.'',''The findings must be carefully qualified lest the reader draw conclusions that the evidence does not support.'']','Option D: ''lest + subject + base verb (no -s)'' = present subjunctive after ''lest.''','easy'),

  -- BLOCK 78: Formal subjunctive in academic writing (8 ex)
  (cid,78,255,'gap_fill','[Academic writing] It is essential that research _____ (conduct/passive) with _____ (rigorous) _____ _____ (attention) to _____ _____ (methodological) _____ (standard) and that _____ (finding) _____ (report/passive) _____ (accurately) and _____ (transparently), _____ _____ (whatever) _____ (their) _____ (implication) for the _____ (prevailing) _____ (consensus).','be conducted / rigorous / attention / methodological / standards / findings / be reported / accurately / transparently / whatever / their / implications / prevailing / consensus',NULL,'''It is essential that research be conducted...findings be reported'' = parallel passive subjunctives; formal academic register.','hard'),
  (cid,78,256,'gap_fill','[Academic writing] The _____ (convention) _____ (demand) that _____ _____ _____ (all/significant/finding) _____ (report/passive) regardless of _____ _____ _____ (whether/they) _____ _____ _____ _____ _____ (confirm/or/disconfirm) the _____ (hypothesis), lest _____ (publication) _____ _____ _____ _____ (bias/systematically/distort/passive) the _____ _____ _____ _____ _____ (accumulated/body/of/scientific/knowledge).','convention / demands / all significant findings / be reported / whether they / confirm or disconfirm / hypothesis / publication / bias systematically distort / accumulated body of scientific knowledge',NULL,'''Demand that findings be reported'' (passive subjunctive) + ''lest publication bias distort'' (present subjunctive).','hard'),
  (cid,78,257,'gap_fill','[Academic writing] The _____ (committee) _____ (recommend) that this _____ (paper) _____ _____ _____ (be/substantially/revise/passive) before _____ (publication) and that the _____ (author) _____ (address) in _____ (particular) the _____ (significant) _____ _____ _____ _____ _____ _____ (weakness/in/causal/identification/identify/passive) _____ (by) _____ (reviewer).','committee / recommends / paper / be substantially revised / publication / author / address / particular / significant / weakness in causal identification identified / reviewers',NULL,'''Recommend that paper be substantially revised...and that author address'' = passive + active present subjunctives.','hard'),
  (cid,78,258,'gap_fill','[Academic writing] It is vital that _____ _____ (all/conclusion) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (ground/passive/firmly/in/the/available/evidence) and that _____ _____ _____ (speculative/claim) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (clearly/distinguish/passive/from/those/that/the/evidence/more/directly/support).','all conclusions / be grounded firmly in the available evidence / speculative claims / be clearly distinguished from those that the evidence more directly supports',NULL,'''It is vital that conclusions be grounded...speculative claims be clearly distinguished'' = two parallel passive subjunctives.','hard'),
  (cid,78,259,'gap_fill','[Academic writing] The _____ (ethics) _____ (board) _____ (requires) that _____ (all) _____ (research) _____ _____ _____ _____ _____ _____ _____ (involving/human/subject) _____ _____ _____ _____ (receive/passive) _____ (prior) _____ _____ (approval) and that _____ (participant) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (provide/passive/with/full/information/about/the/nature) of their _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (participation/and/the/potential/risk/and/benefit/involve).','ethics / board / requires / all / research / involving human subjects / receive prior approval / participants / be provided with full information about the nature / participation and the potential risks and benefits involved',NULL,'''Require that research receive prior approval...participants be provided'' = two subjunctives in research context.','hard'),
  (cid,78,260,'gap_fill','[Academic writing] Good academic practice _____ _____ (demand) that researchers _____ (disclose) all _____ (potential) _____ _____ (conflict) of _____ (interest) and that this _____ (disclosure) _____ (allow/passive) _____ (reader) to _____ _____ _____ (assess/for/themselves) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (whether/such/conflict/may/have/influence/passive/the/finding).','demands / disclose / potential / conflicts / interest / disclosure / be allowed / readers / assess for themselves / whether such conflicts may have influenced the findings',NULL,'''Demand that researchers disclose...disclosure be allowed...readers assess'' = three present subjunctives.','hard'),
  (cid,78,261,'gap_fill','[Academic writing] It is _____ _____ (important) that _____ _____ _____ (future/researcher) _____ _____ _____ _____ _____ _____ _____ _____ _____ (build/on/this/analysis) rather than _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (simply/replicate/it) and that they _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (attend/closely/to/the/methodological/limitation/identify/passive) in this _____ _____ _____ (paper/when/design) _____ _____ _____ _____ _____ _____ (their/own/study).','important / future researchers / build on this analysis / simply replicate it / attend closely to the methodological limitations identified / paper when designing / their own studies',NULL,'''It is important that researchers build...and that they attend closely'' = two present subjunctives with guidance function.','hard'),
  (cid,78,262,'multiple_choice','[Academic writing] Which sentence MOST correctly uses the formal subjunctive?','The protocol stipulates that all data be archived for a minimum of ten years following publication.','[''The protocol stipulates that all data is archived for ten years after publication.'',''The protocol stipulates that all data are archived for ten years after publication.'',''The protocol stipulates that all data be archived for a minimum of ten years following publication.'',''The protocol stipulates that all data should be archived for ten years after publication.'']','Option C: ''stipulate that + subject + base form (be)'' = formal present subjunctive. ''Is/are'' uses indicative; ''should be'' is a weaker modal alternative.','easy'),

  -- BLOCK 79: TOEFL Reading — Subjunctive (8 ex)
  (cid,79,263,'multiple_choice','[TOEFL Reading] ''The committee recommends that the government commission an independent review.'' The word ''commission'' is in the subjunctive because:','it follows ''recommends that'' and takes the base form regardless of subject.','[''it is an infinitive'',''it follows \''recommends that\'' and takes the base form regardless of subject.'',''it is a gerund'',''it is past tense'']','Present subjunctive after ''recommend that'' = base form (no -s, no inflection). ''Commission'' = base form.','easy'),
  (cid,79,264,'gap_fill','[TOEFL Reading] ''It is essential that the review _____ (conduct/passive) independently and its findings _____ (make/passive) public.'' The correct forms are:','be conducted / be made',NULL,'''It is essential that + subject + be + past participle'' = passive subjunctive.','medium'),
  (cid,79,265,'gap_fill','[TOEFL Reading] ''The author argues that if only the evidence _____ (be) stronger, more confident policy prescriptions _____ (be/possible).'' The correct forms are:','were / would be',NULL,'''If only the evidence were stronger, would be possible'' = past subjunctive (unreal present); ''were'' not ''was'' in formal writing.','medium'),
  (cid,79,266,'gap_fill','[TOEFL Reading] ''The organization behaves as if it _____ (be) immune to external accountability pressures.'' The correct form is:','were',NULL,'''As if + were'' = past subjunctive for unreal present comparison (formal academic register).','easy'),
  (cid,79,267,'gap_fill','[TOEFL Reading] ''The board insists that the director _____ (appear) before the committee and _____ (provide) full documentation.'' The correct forms are:','appear / provide',NULL,'''Insist that + subject + base verb'' (appear, provide — no -s) = present subjunctive.','easy'),
  (cid,79,268,'gap_fill','[TOEFL Reading] ''Care must be taken lest a premature conclusion _____ (draw/passive) from this preliminary analysis.'' The correct form is:','be drawn',NULL,'''Lest + subject + be + past participle'' = passive subjunctive; ''be drawn'' = base form passive.','medium'),
  (cid,79,269,'gap_fill','[TOEFL Reading] ''The researcher wishes she _____ (have) access to a larger sample — if only she _____ (do), the generalizability of the findings would be considerably greater.'' The correct forms are:','had / did',NULL,'''Wishes she had'' = past simple after wish (unreal present); ''if only she did'' = same.','medium'),
  (cid,79,270,'multiple_choice','[TOEFL Reading] ''Would rather the government proceeded more cautiously before committing itself to the reform.'' Which form of ''proceed'' is used and why?','Past simple ''proceeded'' because ''would rather'' expresses an unreal preference about someone else''s action.','[''Base form because it follows a modal'',''Past simple \''proceeded\'' because \''would rather\'' expresses an unreal preference about someone else''s action.'',''Past perfect because it refers to past events'',''Present participle because it follows \''rather\"'']','''Would rather + subject + past simple/subjunctive'' = unreal preference about another''s action.','easy'),

  -- BLOCK 80: TOEFL Speaking — Subjunctive (8 ex)
  (cid,80,271,'production','[TOEFL Speaking — 45s] Summarize a reading on institutional reform using subjunctive structures throughout.','',NULL,'The reading proposes that governance reform be approached as a multi-stage process and recommends that any new oversight framework be designed with both formal and informal dimensions in mind. It stipulates that impact evaluations be conducted at regular intervals and that the findings be made publicly available. The reading insists that all stakeholders have the opportunity to participate in the consultation process and that their contributions be taken seriously. It is vital, the reading argues, that practitioners not assume that good design alone is sufficient — it is essential that attention also be given to implementation capacity and to the political conditions necessary for sustained reform.','hard'),
  (cid,80,272,'production','[TOEFL Speaking — 45s] The professor challenges the reading. Use subjunctive structures throughout.','',NULL,'The professor demands that the reading be subjected to more critical scrutiny than it has typically received. She insists that its methodological assumptions be examined carefully and that its conclusions not be taken as more definitive than the evidence warrants. It is important, she argues, that readers recognize the limitations of the comparative dataset and that they not assume that findings from one context be automatically applicable to others. The professor recommends that future research adopt a more rigorous approach to causal identification and that researchers ensure that their conclusions be grounded firmly in the available evidence rather than in theoretical priors. She wishes the reading had been more explicit about these limitations — if only it had, it would have been more persuasive.','hard'),
  (cid,80,273,'production','[TOEFL Speaking — 60s] Compare reading and professor using subjunctive throughout.','',NULL,'The reading and the professor both engage seriously with the question of what conditions are necessary for successful governance reform, though they differ significantly in the conclusions they reach. The reading recommends that policymakers give priority to formal institutional design and stipulates that any reform framework incorporate robust accountability mechanisms from the outset. It insists that impact evaluations be conducted independently and that their findings be made public. The professor, by contrast, demands that greater attention be paid to the informal dimensions of governance and insists that practitioners not assume that formal design is sufficient on its own. It is essential, she argues, that both formal and informal factors be addressed simultaneously if reform is to achieve its stated objectives. She wishes that the reading had engaged more seriously with the literature on informal institutions — if only it had, she suggests, its recommendations would be considerably more nuanced. The two perspectives together suggest that it is vital that any comprehensive reform strategy attend to the full complexity of the governance challenge and that it be designed with realistic expectations about what formal institutional changes alone can accomplish.','hard'),
  (cid,80,274,'gap_fill','[TOEFL Speaking] The reading recommends that the oversight body _____ (establish/passive) and that it _____ _____ _____ _____ _____ _____ _____ (be/given/the/authority/and/resource) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (necessary/to/carry/out/its/mandate/effectively).','be established / be given the authority and resources / necessary to carry out its mandate effectively',NULL,'''Recommend that body be established...be given'' = two passive subjunctives.','hard'),
  (cid,80,275,'gap_fill','[TOEFL Speaking] The professor insists that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/methodology/of/the/study/be/examine/passive/more/critically) before any of its conclusions _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (accept/passive/as/reliable/evidence).','the methodology of the study be examined more critically / be accepted as reliable evidence',NULL,'''Insist that the methodology be examined...conclusions be accepted'' = passive subjunctives.','hard'),
  (cid,80,276,'gap_fill','[TOEFL Speaking] It is vital, the reading argues, that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (practitioners/not/assume/that/formal/design/be/sufficient) without also attending to implementation capacity and political context.','practitioners not assume that formal design be sufficient',NULL,'''It is vital that practitioners not assume that design be sufficient'' = negative present subjunctive.','hard'),
  (cid,80,277,'gap_fill','[TOEFL Speaking] The professor wishes the reading _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (had/been/more/explicit/about/the/limitations/of/its/methodology) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (if/only/it/had/its/conclusions/would/have/been/considerably/more/persuasive).','had been more explicit about the limitations of its methodology / if only it had its conclusions would have been considerably more persuasive',NULL,'''Wishes the reading had been'' (past perfect subjunctive for past regret) + ''if only it had, would have been.''','hard'),
  (cid,80,278,'multiple_choice','[TOEFL Speaking] Which subjunctive-based sentence MOST effectively demonstrates academic fluency?','The reading stipulates that all evidence be assessed rigorously and that any conclusions drawn be grounded in the full body of available data.','[''The reading says all evidence should be rigorously assessed and conclusions should be grounded.'',''The reading stipulates that all evidence be assessed rigorously and that any conclusions drawn be grounded in the full body of available data.'',''The reading says that all evidence needs rigorous assessing and grounded conclusions.'',''The reading insists evidence is assessed and conclusions are grounded.'']','Option B: ''stipulates that evidence be assessed...conclusions drawn be grounded'' = double passive subjunctive, high academic register.','medium'),

  -- BLOCK 81: TOEFL Writing — produção (8 ex)
  (cid,81,279,'production','[TOEFL Writing — 200 words] Write a body paragraph on institutional reform requirements using subjunctive structures.','',NULL,'For governance reform to succeed, it is essential that a number of conditions be satisfied simultaneously — conditions that the literature has identified with growing confidence over the past several decades, even if the mechanisms through which they produce their effects remain incompletely understood. It is vital that the formal design of any new institutional arrangement be grounded in realistic analysis of the political economy in which it will operate, lest it be rendered ineffective by predictable opposition from those whose interests the reform threatens. The framework must require that implementing agencies be given the resources and authority they need to carry out their mandated functions and that their performance be assessed against clear, measurable objectives. It is crucial that accountability mechanisms be designed to be genuinely independent of those whose behavior they are meant to oversee, and that the findings of any performance assessment be made publicly available so that external actors can exercise the kind of accountability pressure that internal mechanisms alone are unlikely to generate. The reform must also insist that feedback mechanisms be established from the outset — systems that allow evidence of underperformance to be detected early and that require those responsible to respond with concrete corrective action.','hard'),
  (cid,81,280,'production','[TOEFL Writing — 200 words] Write a body paragraph comparing the reading and lecture using subjunctive structures.','',NULL,'The reading demands that governance reform be treated as a technical problem with a determinable solution, while the professor insists that it be understood as a fundamentally political challenge whose resolution requires more than good design. The reading stipulates that any reform framework incorporate robust accountability mechanisms and recommends that performance evaluations be conducted by independent bodies. The professor, by contrast, argues that it is vital that practitioners not assume that formal accountability is sufficient to produce the accountability behavior that mechanisms are designed to encourage — she wishes the reading had engaged more seriously with the literature on informal norms and incentive alignment. It is essential, in the professor''s view, that reform strategies attend to both the formal and informal dimensions of governance and that they be designed with realistic expectations about the pace of behavioral change. The synthesis of these perspectives suggests that any comprehensive approach to governance reform must require that attention be given to the full complexity of the challenge — lest practitioners fall into the trap of assuming that formal design is sufficient and subsequently be surprised by the gap between the outcomes anticipated and those actually achieved.','hard'),
  (cid,81,281,'gap_fill','[TOEFL Writing] The protocol demands that all _____ (research/involve/gerund) human subjects _____ _____ _____ _____ (receive/passive) _____ (prior) _____ (ethical) _____ (approval) and that participants _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (provide/passive/with/full/and/accurate/information) about their _____ _____ _____ _____ _____ _____ (right/to/withdraw).','research involving / receive prior / ethical / approval / be provided with full and accurate information / rights to withdraw',NULL,'''Demand that research receive approval...participants be provided'' = subjunctives in research ethics context.','hard'),
  (cid,81,282,'gap_fill','[TOEFL Writing] It is vital that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/argument/present/passive/in/this/paper/not/take/passive/as/more/definitive) than the _____ _____ _____ _____ _____ _____ _____ (evidence/on/which/it/base/passive) warrants.','the argument presented in this paper not be taken as more definitive / evidence on which it is based',NULL,'''It is vital that the argument not be taken'' = negative passive subjunctive; ''evidence on which it is based.''','hard'),
  (cid,81,283,'gap_fill','[TOEFL Writing] The _____ (convention) _____ (demands) that all _____ _____ _____ _____ (significant/finding/report/passive) regardless of their _____ _____ (direction) lest _____ _____ _____ (publication) _____ _____ _____ _____ (bias/distort/passive) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (available/evidence/base/and/mislead/passive) future researchers.','convention / demands / significant findings be reported / direction / publication / bias distort / available evidence base and mislead',NULL,'''Demands that findings be reported...lest bias distort...and mislead'' = subjunctive + lest + subjunctive.','hard'),
  (cid,81,284,'gap_fill','[TOEFL Writing] It is _____ _____ (crucial) that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/conclusion/of/this/analysis/be/understood/as/a/preliminary/contribution/to/an/ongoing/scholarly/conversation) rather than _____ _____ _____ _____ _____ _____ (as/a/definitive/account/of/the/phenomenon).','crucial / the conclusions of this analysis be understood as a preliminary contribution to an ongoing scholarly conversation / as a definitive account of the phenomenon',NULL,'''It is crucial that the conclusions be understood'' (passive subjunctive) + ''rather than as a definitive account.''','hard'),
  (cid,81,285,'gap_fill','[TOEFL Writing] Good _____ (academic) _____ (practice) _____ (demands) that researchers _____ (acknowledge) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/limitation/of/their/analysis) lest _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (overconfident/claim/undermine/passive/the/credibility/of/legitimate/finding).','academic / practice / demands / acknowledge / the limitations of their analysis / overconfident claims undermine the credibility of legitimate findings',NULL,'''Demands that researchers acknowledge limitations'' (present subjunctive) + ''lest overconfident claims undermine credibility.''','hard'),
  (cid,81,286,'multiple_choice','[TOEFL Writing] Which sentence MOST effectively uses the subjunctive in an integrated essay conclusion?','The analysis suggests that it is vital that practitioners attend to both formal and informal dimensions of governance and that any reform strategy be grounded in realistic assessment of the political conditions in which it will operate.','[''The analysis suggests practitioners should attend to both formal and informal dimensions.'',''The analysis suggests that it is vital that practitioners attend to both formal and informal dimensions of governance and that any reform strategy be grounded in realistic assessment of the political conditions in which it will operate.'',''The analysis suggests that practitioners must attend to governance dimensions and strategy should be grounded.'',''It is vital that practitioners attend to governance because strategy is grounded.'']','Option B: ''it is vital that practitioners attend...reform strategy be grounded'' = two present subjunctives nested in an integrated thesis.','hard'),

  -- BLOCK 82: Produção avançada (7 ex)
  (cid,82,287,'production','[TOEFL Writing — 200 words] Write a conclusion on what governance reform requires using subjunctive structures throughout.','',NULL,'For governance reform to achieve its stated objectives, it is essential that a number of demanding conditions be satisfied simultaneously — conditions that are easy to enumerate but difficult to create and maintain over time. The analysis demands that we take seriously the full complexity of the challenge and that we resist the temptation to reduce it to any single dimension, whether formal or informal, technical or political, design or implementation. It is vital that practitioners not assume that good design is sufficient and that the adoption of formal accountability mechanisms automatically produces the accountability behavior those mechanisms are intended to encourage. It is equally important that researchers ensure that their conclusions be grounded firmly in evidence and that they acknowledge the limitations of their analysis lest overconfident claims undermine the credibility of legitimate findings. The field recommends that future research attend both to the theoretical gaps identified in this analysis and to the practical implications of what is already known — it is crucial that the boundary between what we know and what we merely believe be clearly marked. If only we had been clearer about this boundary earlier, much of the confusion that has characterized debates in this field might have been avoided. The work, in any case, continues.','hard'),
  (cid,82,288,'gap_fill','[Final] It is essential that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/study/of/governance/reform/continue/to/develop/the/methodological/tools/and/theoretical/framework) needed to generate _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (genuinely/cumulative/and/policy-relevant/knowledge).','the study of governance reform continue to develop the methodological tools and theoretical frameworks / genuinely cumulative and policy-relevant knowledge',NULL,'''It is essential that the study continue to develop'' (present subjunctive: ''continue,'' not ''continues'').','hard'),
  (cid,82,289,'gap_fill','[Final] The _____ (field) _____ (demands) that its _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (most/important/finding/communicate/passive/clearly) to practitioners and that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/gap/between/research/and/practice/systematically/address/passive) through investment in bridging institutions.','field / demands / most important findings be communicated clearly / the gap between research and practice systematically addressed',NULL,'''Demand that findings be communicated...gap systematically addressed'' = two passive subjunctives.','hard'),
  (cid,82,290,'gap_fill','[Final] If _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (only/the/insight/of/this/analysis/be/more/widely/know/passive), the _____ _____ _____ _____ _____ _____ _____ _____ (quality/of/governance/reform) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (practice/might/be/considerably/higher) than it _____ _____ (currently/be).','only the insights of this analysis were more widely known / quality of governance reform / practice might be considerably higher / currently is',NULL,'''If only the insights were more widely known, practice might be considerably higher than it currently is'' = unreal present.','hard'),
  (cid,82,291,'gap_fill','[Final] It is _____ _____ (vital) that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/generation/of/practitioner/who/will/implement/tomorrow''s/governance/reform/be/equipped/with/the/best/available/knowledge) about _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (what/determines/whether/reform/succeed).','vital / the generation of practitioners who will implement tomorrow''s governance reforms be equipped with the best available knowledge / what determines whether reform succeeds',NULL,'''It is vital that the generation be equipped with knowledge about what determines whether reform succeeds.''','hard'),
  (cid,82,292,'production','[TOEFL Writing — 200 words] Final capstone: Write a synthesis of the subjunctive-rich academic discourse on governance.','',NULL,'The discourse of governance reform is inherently normative, and the subjunctive mood — the mood of recommendation, insistence, and wish — is accordingly among its most characteristic grammatical features. The field demands that researchers behave rigorously, that practitioners act wisely, and that policymakers be given the best available evidence; it insists that accountability be maintained, that transparency be respected, and that the interests of those who depend on governance be given priority. It is vital that this normative orientation be grounded in realistic assessment of what is possible rather than in aspiration alone — it is essential that the gap between the ideal of good governance and the practical reality of imperfect institutions be honestly acknowledged, lest the literature generate expectations that cannot be met and thereby undermine confidence in the enterprise of reform itself. If only the history of governance reform were more consistently one of success, these injunctions might carry more weight. As it is, the subjunctive mood of the literature reflects not only its normative ambitions but also its ongoing reckoning with the distance between what it recommends and what the world has managed to deliver. That distance is itself a call to continued effort — it requires that scholars, practitioners, and citizens alike refuse to be satisfied with what is when what ought to be remains achievable.','hard'),

  -- BLOCK 83: Capstone final (7 ex)
  (cid,83,293,'gap_fill','[Final capstone] The paper _____ _____ _____ (concludes/by/recommend) that the field _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (invest/in/the/kind/of/rigorous/cross-disciplinary/research) that _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (alone/be/likely/to/produce/the/kind/of/genuinely/cumulative/knowledge/that/the/governance/challenge/requires).','concludes by recommending / invest in the kind of rigorous cross-disciplinary research / alone be likely to produce the kind of genuinely cumulative knowledge that the governance challenge requires',NULL,'''Recommending that the field invest'' (present subjunctive: ''invest,'' not ''invests'') + ''that alone be likely to produce.''','hard'),
  (cid,83,294,'gap_fill','[Final capstone] It is _____ _____ (crucial) that the _____ _____ _____ (conclusion/of/this/analysis) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (not/take/passive/as/more/authoritative/than/the/evidence) on which they _____ _____ _____ _____ _____ _____ (rest/warrant/passive).','crucial / conclusions of this analysis / not be taken as more authoritative than the evidence / rest warrants',NULL,'''It is crucial that conclusions not be taken as more authoritative than the evidence warrants.''','hard'),
  (cid,83,295,'gap_fill','[Final capstone] The _____ _____ _____ _____ _____ _____ _____ _____ (scholarship/demand) that we _____ _____ (not/rest) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (satisfied/with/what/is/known) but that we _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (continue/to/push/the/frontier/of/understanding/toward/what/is/as/yet/unknown).','scholarship / demands / not rest / satisfied with what is known / continue to push the frontier of understanding toward what is as yet unknown',NULL,'''Demands that we not rest satisfied...but that we continue to push'' = two present subjunctives.','hard'),
  (cid,83,296,'production','[TOEFL Writing — 200 words] Final synthesis on subjunctive and academic discourse in governance.','',NULL,'The subjunctive mood, often described as a relic of older grammatical systems in English, remains a living and productive feature of formal academic discourse — nowhere more so than in the literature on governance reform, which is inherently a literature of recommendation, insistence, and normative aspiration. When scholars write that it is vital that reform strategies be grounded in realistic analysis, or that practitioners not assume that formal design is sufficient, they are expressing not merely their personal preferences but the normative commitments of a scholarly tradition that takes seriously its responsibility to the practical world in which governance operates. It is essential that this normative orientation be disciplined by epistemological humility — that claims about what ought to be done be grounded in honest assessment of what is known, lest the literature generate unrealistic expectations and thereby undermine the credibility of the advice it offers. If only the history of governance reform were more encouraging, this balance between aspiration and realism would be easier to strike. As it is, the field demands that scholars resist both the temptation of cynicism — the counsel that nothing can be done — and the temptation of overconfidence — the counsel that the answers are already in hand. It is in navigating this tension that the intellectual integrity of governance scholarship ultimately consists.','hard'),
  (cid,83,297,'gap_fill','[Final capstone] If _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (only/the/governance/reform/effort/of/the/past/several/decades/have/been/more/consistently/successful), the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (case/for/continued/investment/in/the/enterprise/of/reform/would/be/considerably/stronger) than it currently is.','only the governance reform efforts of the past several decades had been more consistently successful / case for continued investment in the enterprise of reform would be considerably stronger',NULL,'''If only the efforts had been more consistently successful, the case would be considerably stronger'' = past regret.','hard'),
  (cid,83,298,'gap_fill','[Final capstone] The _____ _____ (field) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (insist/that/scholars/be/honest) about what is _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (known/and/what/remain/uncertain) lest the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (authority/of/the/discipline/be/undermine/passive/by/overconfident/claim) that the evidence does not support.','field / insists that scholars be honest / known and what remains uncertain / authority of the discipline be undermined by overconfident claims',NULL,'''Insists that scholars be honest'' (present subjunctive) + ''lest authority be undermined'' (passive subjunctive).','hard'),
  (cid,83,299,'gap_fill','[Final capstone] It is vital that this _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (paper/have/contribute/passive) — however _____ _____ _____ _____ (modestly) — to _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/accumulation/of/knowledge) about _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (what/makes/governance/work) and that it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (inspire/future/researcher/to/pursue/the/question/with/the/rigor/and/imagination/that/it/deserves).','paper have contributed / modestly / the accumulation of knowledge / what makes governance work / inspire future researchers to pursue the question with the rigor and imagination that it deserves',NULL,'''It is vital that this paper have contributed'' (past subjunctive) + ''that it inspire future researchers" (present subjunctive).','hard'),
  (cid,83,300,'production','[TOEFL Writing — Final capstone] Write a 200-word culminating paragraph using subjunctive mood throughout on the normative ambitions of governance scholarship.','',NULL,'The governance of public affairs demands that we not be satisfied with what is and that we work persistently toward what ought to be. It requires that scholarship be rigorous and that its conclusions be honest, that practitioners be wise and that their choices be informed by the best available evidence, and that citizens be engaged and that their voices be heard in the processes through which collective decisions are made. It is essential that none of these requirements be treated as mere aspiration — they are, rather, the conditions that distinguish governance worthy of the name from its many pale imitations. It is vital that the scholarly community be held to these standards and that it hold itself to them regardless of the pressures that would counsel a more comfortable accommodation with the gap between what governance is and what it should be. If only the history of governance were one of steady progress toward these ideals, the normative ambitions of the field would be easier to sustain. As it is, the demands of the subjunctive — that we insist, recommend, and require — are a reminder that the work is ongoing and that the gap between aspiration and reality is itself the most powerful argument for continuing to close it. The field requires it; the world demands it; and the populations whose welfare depends on effective governance deserve nothing less.','hard')

